-- ── 3. Montaj seansları ──────────────────────────────────────
-- step_name / seq_no / is_final_step assembly_steps'ten geliyor,
-- dosyadan taşınmıyor.
INSERT INTO public.montaj_sessions
  (session_id,sku,step_id,step_name,seq_no,durum,email,operator_id,
   is_final_step,start_time,end_time,qty,worker_count,workers)
SELECT split_part(r,'|',1), split_part(r,'|',3), split_part(r,'|',4),
       s.step_name, s.seq_no,
       CASE split_part(r,'|',9) WHEN 'C' THEN 'tamamlandi' ELSE 'montajda' END,
       split_part(r,'|',10)||'@vigowood.com',
       split_part(split_part(r,'|',5),'+',1),
       s.is_final_step,
       (split_part(r,'|',2)||' '||NULLIF(split_part(r,'|',6),'')||'+03')::timestamptz,
       (split_part(r,'|',2)||' '||NULLIF(split_part(r,'|',7),'')||'+03')::timestamptz,
       split_part(r,'|',8)::numeric,
       NULLIF(array_length(string_to_array(split_part(r,'|',5),'+'),1),0),
       to_jsonb(string_to_array(NULLIF(split_part(r,'|',5),''),'+'))
